const body = $('Webhook').first().json.body;
const model = body.topaz_model || 'Standard V2';

// Helper: true only if the field was actually sent (not missing/empty)
const has = (v) => v !== undefined && v !== null && v !== '';

// Base payload — always sent (these always have a value from the UI)
const payload = {
  image_url:         body.image_url || body.image_urls?.[0] || '',
  model:             model,
  upscale_factor:    Math.min(Math.max(parseFloat(body.upscale_factor) || 2, 1), 4),
  output_format:     ['jpeg','png'].includes(body.output_format) ? body.output_format : 'jpeg',
  subject_detection: ['All','Foreground','Background'].includes(body.subject_detection) ? body.subject_detection : 'All',
  face_enhancement:  !(body.face_enhancement === false || body.face_enhancement === 'false'),
};

if (has(body.crop_to_fill)) payload.crop_to_fill = body.crop_to_fill === true || body.crop_to_fill === 'true';

// Face enhancement fine controls — only if actually provided
if (has(body.face_enhancement_strength))   payload.face_enhancement_strength   = parseFloat(body.face_enhancement_strength);
if (has(body.face_enhancement_creativity)) payload.face_enhancement_creativity = parseFloat(body.face_enhancement_creativity);

// Sharpening controls — Standard V2, High Fidelity V2, Low Resolution V2, CGI, Text Refine, Redefine
const sharpenModels = ['Standard V2','High Fidelity V2','Low Resolution V2','CGI','Text Refine','Redefine'];
if (sharpenModels.includes(model)) {
  if (has(body.sharpen))         payload.sharpen         = parseFloat(body.sharpen);
  if (has(body.denoise))         payload.denoise         = parseFloat(body.denoise);
  if (has(body.fix_compression)) payload.fix_compression = parseFloat(body.fix_compression);
}

// Text Refine only
if (model === 'Text Refine') {
  if (has(body.strength)) payload.strength = parseFloat(body.strength);
}

// Redefine only
if (model === 'Redefine' || model === 'Wonder 3') {
  if (has(body.creativity)) payload.creativity = parseInt(body.creativity, 10);
  if (has(body.texture))    payload.texture    = parseInt(body.texture, 10);
  const prompt = (body.prompt || '').trim().slice(0, 1024);
  if (prompt) {
    payload.prompt = prompt;
  } else {
    payload.autoprompt = true;
  }
}

// Recovery V2 only
if (model === 'Recovery V2') {
  if (has(body.detail)) payload.detail = parseFloat(body.detail);
}

return [{ json: payload }];

