      NumImages:    Number(body.num_images) || 1,
      ImageURLs:    Array.isArray(body.image_urls) 
                      ? body.image_urls.join('\n') 
                      : (body.image_urls || ''),
      WebhookURL:   body.webhookUrl || '',
      Status:       'Processing',
    }
  }
}];

